INSERT INTO scheduled_tasks (id, agent_id, name, description, schedule_type, cron_expression, action, action_params, status, last_run, next_run, run_count, fail_count, created_at, enabled) VALUES
('cfo-daily-reconciliation', 'cfo-financial', 'Daily Transaction Reconciliation', 'Reconcile daily transactions, categorize uncategorized entries, update cash position', 'cron', '0 21 * * *', 'custom_prompt', '{"prompt":"Execute Daily Transaction Reconciliation. Step 1: Query financial_log for today''s entries. Step 2: Identify uncategorized transactions — flag for review. Step 3: Calculate daily net position (income - expenses). Step 4: Check for anomalies — duplicate entries, unusual amounts, out-of-pattern spending. Step 5: Update current cash position from financial_log cumulative totals. Step 6: Cross-reference with activity_log for billable vs non-billable time correlation. Produce: 1) Daily transaction summary — count, total income, total expenses, net, 2) Uncategorized transactions flagged — list with suggested categories, 3) Anomaly report — any unusual patterns detected, 4) Current cash position and runway estimate. If no transactions today: reply HEARTBEAT_OK. If transactions logged: produce brief reconciliation summary.","priority":"P2"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1),
('cfo-weekly-cashflow', 'cfo-financial', 'Weekly Cashflow Review', 'Weekly cashflow analysis with budget compliance and upcoming obligations', 'cron', '0 19 * * 0', 'custom_prompt', '{"prompt":"Execute Weekly Cashflow Review. Step 1: Query financial_log with period=past_week for comprehensive weekly data. Step 2: Calculate weekly cashflow — total income, total expenses, net position. Step 3: Analyze spending by category — which categories are over/under budget? Step 4: Review project burn rates — are active projects on budget? Step 5: Identify upcoming financial obligations — invoices due, subscriptions, bills in next 7 days. Step 6: Cross-reference with COO reports for operational cost context. Produce: 1) Weekly cashflow report — income, expenses, net, trend vs previous week, 2) Budget compliance by category — % of budget used, over/under indicators, 3) Project financial health — budget vs actual for active projects, 4) Upcoming obligations — list with dates and amounts, 5) Cash position and runway estimate. Save weekly summary to reports DB via lifeos_create_report. SYSTEMIC FLAG CHECK: If weekly expenses exceed 120% of budget or cashflow negative for 2+ consecutive weeks → send message.send to ceo-strategic with financial pattern flag. Do NOT write to systemic_journal.","priority":"P1"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1),
('cfo-monthly-close', 'cfo-financial', 'Monthly Financial Close', 'Monthly financial close with P&L analysis, budget variance, and runway calculation', 'cron', '0 17 L * *', 'custom_prompt', '{"prompt":"Execute Monthly Financial Close. Step 1: Query financial_log with period=past_month for comprehensive monthly data. Step 2: Generate P&L analysis — revenue by source, expenses by category, net profit/loss. Step 3: Calculate budget variance — actual vs budgeted for each category. Step 4: Compute key metrics — burn rate (monthly spend), runway (months of capital remaining), margin (profit/revenue %), budget compliance (%). Step 5: Update months DB with financial summary fields. Step 6: Compare month-over-month trends — revenue growth, expense growth, margin direction. Produce: 1) Monthly P&L statement — revenue, expenses, net, margin %, 2) Budget variance report — each category with actual vs budgeted, variance %, 3) Key financial metrics — burn rate, runway, margin, compliance, 4) Month-over-month trends — growth rates, trajectory direction, 5) Capital allocation assessment — where capital was deployed, ROI indicators. Save comprehensive monthly financial report to reports DB via lifeos_create_report. Update months DB financial fields. SYSTEMIC FLAG CHECK: If runway < 6 months, or margin declining 3+ consecutive months, or expenses growing faster than revenue → send message.send to ceo-strategic with systemic financial pattern flag.","priority":"P1"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1),
('cfo-quarterly-review', 'cfo-financial', 'Quarterly Financial Review', 'Quarterly financial review with OKR progress, capital reallocation, and strategic assessment', 'cron', '0 14 1 1,4,7,10 *', 'custom_prompt', '{"prompt":"Execute Quarterly Financial Review. Step 1: Query financial_log with period=past_quarter for comprehensive quarterly data. Step 2: Assess quarterly financial OKR progress — compare targets vs actuals for revenue, profit, budget compliance. Step 3: Analyze quarter-over-quarter trends — revenue growth %, expense trends, margin trajectory. Step 4: Identify capital reallocation opportunities — underperforming areas to reduce, high-performing areas to invest in. Step 5: Review project portfolio ROI — which projects delivered returns, which underperformed. Step 6: Generate strategic financial posture assessment — runway, growth trajectory, risk factors. Produce: 1) Quarterly financial report — revenue, expenses, net, OKR achievement %, 2) Quarter-over-quarter comparison — growth rates, trend direction, 3) Capital reallocation recommendations — shift from X to Y based on performance, 4) Project ROI analysis — returns by project, investment efficiency, 5) Strategic financial risks — runway concerns, revenue concentration, margin pressure. Save comprehensive quarterly financial report to reports DB. SYSTEMIC FLAG CHECK: If quarterly revenue declined, or runway < 3 months, or >80% revenue from single source → send message.send to ceo-strategic with critical financial pattern flag.","priority":"P1"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1);
